package ru.nksk.lctapp.data.game.content

/** Display text transcribed from campaign-lore.figma.json; executable adaptation is in BundledStoryCampaign. */
internal data class SourceLoreCard(val id: String, val title: String, val body: String, val optional: Boolean, val sourceUrl: String)

internal val sourceLoreCards: List<SourceLoreCard> = listOf(
    SourceLoreCard("G1.01", "Ночь наблюдений", "«Через несколько недель откроется старый небесный зал. Но телескоп пока не готов. Соберём комплект постепенно - это наша большая цель».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3831"),
    SourceLoreCard("G1.02", "Странный знак на ящике", "«На ящике странная метка». Бобёр: «Такие знаки ставили на грузах для северной башни. Только башня давно погасла…»", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3845"),
    SourceLoreCard("G1.03", "Пластина с тем же знаком", "Смотритель: «Я не ошибся. Тот же знак». Надпись на пластине почти скрыта налётом - её придётся очистить.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3859"),
    SourceLoreCard("G1.04", "Запись в журнале грузов", "Бобёр находит старую запись: грузы со знаком отправлялись не прямо к башне, а через дорожные посты. Значит, сеть была больше одной башни.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3873"),
    SourceLoreCard("G1.05", "«Три ответа - в одном свете»", "Под налётом проступает фраза: «Когда северная башня погаснет, ищи три ответа в одном свете». Смотритель: «Пока не понимаю. Но это уже точно не случайная метка».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3887"),
    SourceLoreCard("G1.06", "Старая карта", "На старой карте отмечены мост и башня. Рядом с башней - знакомый знак. Теперь ясно: это реальное место, а не портовая байка.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3901"),
    SourceLoreCard("G1.07", "Старая эмблема службы", "«Похоже, это был не просто знак груза». На обороте эмблемы выбито: «служба путей». Название пока неполное, но сеть явно была официальной.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3915"),
    SourceLoreCard("G1.08", "Схема трёх линз", "На старом чертеже - три линзы разных цветов. Подпись указывает: порядок задавался на дорожном посту.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3929"),
    SourceLoreCard("G1.09", "Каменный пост", "Три линзы совпадают с архивной схемой. Если посмотреть через них по порядку, на куполе обсерватории появляются три отражения.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3943"),
    SourceLoreCard("G1.10", "Малый телескоп и старый журнал", "Во время настройки Рыжик замечает в журнале: «Северный пост отвечает тремя сигнальными огнями». Цвета совпадают с найденным порядком.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3957"),
    SourceLoreCard("G1.11", "Башня отвечает", "Башня вспыхивает три раза - ровно в найденном порядке. Смотритель тихо говорит: «Она не погасла. Она отвечает».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3971"),
    SourceLoreCard("G1.12", "Ночь наблюдений раскрывает сеть", "Во время Ночи наблюдений старые метки складываются в сеть маршрутов. Смотритель: «Это была целая служба - Смотрители путей. А башня была одним из их узлов. Если хотим узнать больше, придётся готовить настоящую экспедицию».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-3985"),
    SourceLoreCard("G2.01", "Экспедиция к погасшей башне", "«Теперь мы знаем, куда идти. Но старый путь разрушен». Для экспедиции придётся подготовить карту, свет, крепления, мост и транспорт - всё сразу не купить.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4003"),
    SourceLoreCard("G2.02", "Последний груз к башне", "Бобёр вспоминает: последний груз к башне шёл через мост и запасную переправу. «Если мост не выдержит, ищите старую лодочную станцию ниже по реке».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4017"),
    SourceLoreCard("G2.03", "Закрытый мост", "Старый мост почти не пригоден. Можно вложиться в ремонт, искать обход или вернуться позже. На опоре сохранилась та же эмблема сети.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4031"),
    SourceLoreCard("G2.04", "Сигнальный пост за мостом", "За мостом сохранился сигнальный пост. Его линзы направлены не на обсерваторию, а прямо на башню. На корпусе выцарапано: «Проверить ответ перед входом».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4045"),
    SourceLoreCard("G2.05", "Следы недавнего ремонта", "Башня выглядит заброшенной, но кое-что не сходится: одна петля недавно смазана, рядом свежая стружка. Кто-то поддерживал механизм уже после закрытия сети.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4059"),
    SourceLoreCard("G2.06", "Механизм трёх огней", "Вход заперт механизмом из трёх линз. Порядок тот же, что у дорожных постов. Система принимает старый код и открывает внутренний зал.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4073"),
    SourceLoreCard("G2.07", "Комната дежурного", "Журнал показывает: башню не бросили внезапно. Её закрыли по приказу, а один дежурный ещё долго приходил проверять сигналы.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4087"),
    SourceLoreCard("G2.08", "Знак двойной развилки", "На приборе повторяется символ двух дорог. Похоже, «второй путь» был не поэтической фразой, а режимом старого оборудования.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4101"),
    SourceLoreCard("G2.09", "Свиток второго пути", "На свитке сохранилась строка: «Сохрани начало. Измени один выбор. Сравни путь, а не обещание». Ниже - схема устройства, которого в башне нет.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4115"),
    SourceLoreCard("G2.10", "Приёмник указывает на Обсерваторию", "Башенный приёмник оживает и указывает обратно на обсерваторию. Смотрители явно разделили устройство: башня передавала сигнал, а основной механизм находился в другом месте.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4129"),
    SourceLoreCard("G2.11", "Башня посылает обратный код", "Рыжик отправляет тот же трёхцветный код обратно. Через несколько секунд обсерватория отвечает одним белым огнём. Связь между узлами действительно работает.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4143"),
    SourceLoreCard("G2.12", "Хроноскоп", "Свиток и башенный ключ открывают нижний зал. Смотритель читает название на корпусе: «Хроноскоп». Он не меняет прошлое - он показывает, как изменился бы путь после одного другого решения.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2053-4157"),
    SourceLoreCard("G3.01", "Дом исследователя", "«Этот дом принадлежал одному из исследователей сети. Теперь он пустует. Если восстановить его, здесь можно устроить настоящую базу - и, возможно, найти то, что осталось от старых приборов».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3828"),
    SourceLoreCard("G3.02", "Печать Смотрителей на двери", "Под старой краской на двери находится знак Смотрителей. Дом точно связан с сетью. Но замок переделан позже - кто-то жил здесь уже после закрытия башни.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3842"),
    SourceLoreCard("G3.03", "Письмо без отправителя", "В письме одна фраза: «Если прибор снова покажет два пути, не выбирай за человека - покажи разницу». Подписи нет.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3856"),
    SourceLoreCard("G3.04", "Тико приходит помочь", "Тико слышал, что Рыжик восстанавливает старую мастерскую. «Я могу помочь. Но некоторые детали тут очень старые - лучше сначала понять, как они работали, а потом менять».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3870"),
    SourceLoreCard("G3.05", "Деталь Хроноскопа под верстаком", "Под верстаком находится кольцо от Хроноскопа. На нём есть метки калибровки и номер этого дома. Похоже, здесь не просто жили - здесь обслуживали приборы сети.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3884"),
    SourceLoreCard("G3.06", "Старая фотография мастерской", "На старом снимке дом выглядит как мастерская Смотрителей. На столе - тот же тип кольца, который Рыжик нашёл под верстаком.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3898"),
    SourceLoreCard("G3.07", "Инструкция: меняй только одно", "В инструкции есть главное правило: «Для сравнения сохраняй исходные условия и меняй только одно решение. Иначе невозможно понять, что именно изменило путь».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3912"),
    SourceLoreCard("G3.08", "Дом был станцией калибровки", "Под крышей обнаруживается сигнальная линза. Этот дом был станцией калибровки: здесь проверяли приборы перед тем, как отправлять их по сети.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3926"),
    SourceLoreCard("G3.09", "Ящик из затопленного подвала", "В сухом ящике лежат жетоны маршрутов. На каждом - номер и маленькая отметка места. Некоторые номера не совпадают с современной картой города.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3940"),
    SourceLoreCard("G3.10", "Ящики маршрутов", "В столе хранились копии маршрутов. Часть совпадает с известной картой, а часть ведёт дальше - туда, где современных дорог уже нет.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3954"),
    SourceLoreCard("G3.11", "Тико запускает старый тестовый прибор", "Тико удаётся запустить старый тестер. Он не показывает будущее - только сравнивает два набора параметров. «Похоже, Смотрители всё время проверяли свои решения, а не угадывали их».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3968"),
    SourceLoreCard("G3.12", "Дом становится новой базой", "Дом снова работает как мастерская. Тико решает остаться помогать Рыжику. Среди восстановленных карт находятся фрагменты старой карты королевства - их слишком много, чтобы разобрать без настоящего картографа.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-3982"),
    SourceLoreCard("G4.01", "Луна приносит повреждённую карту", "Луна изучает найденные фрагменты: «Это части старой карты королевства. Но тут не просто не хватает кусочков - некоторые маршруты будто специально сняты с карты».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4000"),
    SourceLoreCard("G4.02", "Картографический стол", "Луна объясняет: старые карты нужно собирать слоями. Одна показывает дороги, другая - сигнальные посты, третья - безопасные варианты маршрутов.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4014"),
    SourceLoreCard("G4.03", "Береговой фрагмент", "Среди старых морских карт находится фрагмент сети Смотрителей. Он показывает дешёвый долгий путь вдоль берега и дорогую быструю переправу.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4028"),
    SourceLoreCard("G4.04", "Архивная копия без одной дороги", "На архивной карте есть маршрут, которого нет ни на одной современной. Луна замечает: его не стёрло время - линию аккуратно убрали при перепечатке.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4042"),
    SourceLoreCard("G4.05", "Горный указатель двух путей", "Старый указатель не выбирал путь за путешественника - он показывал два варианта: короткий рискованный и длинный безопасный. Рядом место для жетона маршрута.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4056"),
    SourceLoreCard("G4.06", "Лесной путевой камень", "В лесу сохраняется такой же принцип: не один «правильный» маршрут, а несколько путей с разной ценой по времени и ресурсам.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4070"),
    SourceLoreCard("G4.07", "Хроноскоп сравнивает маршруты", "Луна загружает два старых маршрута в Хроноскоп. Прибор не говорит, какой лучше: он показывает, что изменится, если выбрать другой путь - время, запас и доступные остановки.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4084"),
    SourceLoreCard("G4.08", "На карте появляется пустая область", "Фрагменты сходятся, но между ними остаётся не рваная дыра, а аккуратно пустое место. Луна: «Здесь должен быть целый регион. Его не потеряли - его перестали наносить».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4098"),
    SourceLoreCard("G4.09", "Лунина старая заметка", "Луна признаётся, что видела такой пробел ещё в старых учебных картах. «Учителя говорили, что там просто ничего нет. Но пустые места так аккуратно не рисуют».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4112"),
    SourceLoreCard("G4.10", "Пограничный маяк", "На самом краю современной карты находится старый маяк. Его стрелка указывает прямо в пустую область, а на корпусе есть место для картографического жетона.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4126"),
    SourceLoreCard("G4.11", "Обратная сторона маршрутного жетона", "На обратной стороне жетона оказывается миниатюрная схема места за границей карты. Оно отмечено не как город, а как «узел сети».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4140"),
    SourceLoreCard("G4.12", "Карта королевства собрана", "Карта готова. За границей известных дорог отмечен последний крупный узел Смотрителей. Луна: «Теперь у нас есть направление. Но это уже не прогулка - придётся готовить большую экспедицию».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2054-4154"),
    SourceLoreCard("G5.01", "Большая экспедиция", "Луна: «Маршрут есть. Теперь главное - не потратить всё на старт». Перед выходом нужно собрать оборудование и сохранить обязательный резерв на неизвестные расходы.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3828"),
    SourceLoreCard("G5.02", "Первый маршрут: быстро или надёжно", "Хроноскоп показывает два варианта: короткий путь быстрее, но требует больше запаса; длинный дешевле и безопаснее, но отнимает день. Игра не отмечает один из них «правильным».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3842"),
    SourceLoreCard("G5.03", "Заброшенная релейная станция", "За пределами современной карты стоит релейная станция Смотрителей. Она отключена, но карта внутри показывает: все дальние маршруты сходились к одному последнему узлу.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3856"),
    SourceLoreCard("G5.04", "Хроноскоп не предсказывал будущее", "В журнале сказано прямо: «Хроноскоп не предсказывает, что случится. Он сравнивает, что могло измениться после другого решения. Результат - подсказка для размышления, не обещание».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3870"),
    SourceLoreCard("G5.05", "Запись в штормовом убежище", "На стене Смотрители оставили простое правило: «Если путь неизвестен, резерв - часть маршрута, а не лишний груз».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3884"),
    SourceLoreCard("G5.06", "Центральный узел маршрутов", "Здесь сеть не хранила один маршрут. Для каждого направления есть несколько вариантов - по времени, запасу, погоде и доступным остановкам. «Смотрители не искали единственный правильный путь», - замечает Луна.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3898"),
    SourceLoreCard("G5.07", "Почему сеть закрыли", "После большого шторма дороги изменились. Старые расчёты ещё какое-то время показывали маршруты, которые уже перестали быть безопасными. Смотрители закрыли сеть, пока не могли обновить данные повсюду.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3912"),
    SourceLoreCard("G5.08", "Тико восстанавливает последнее реле", "Тико запускает реле. «Механизм старый, но идея нормальная. Главное - не считать старые данные вечной правдой».", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3926"),
    SourceLoreCard("G5.09", "Луна находит последнюю станцию", "Луна совмещает новые данные с картой королевства. Пустая область наконец получает форму: за долиной находится последняя крупная станция Смотрителей.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3940"),
    SourceLoreCard("G5.10", "Послание последнего Смотрителя", "Последняя запись говорит: «Второй путь нужен не для того, чтобы выбрать за тебя. Он нужен, чтобы спросить: что изменилось и почему? Решение всё равно остаётся твоим».", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3954"),
    SourceLoreCard("G5.11", "Огни сети возвращаются", "После ремонта центрального реле старые маяки отвечают один за другим. Сеть снова может передавать сигналы, но теперь её карты будут обновляться новыми путешественниками.", true, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3968"),
    SourceLoreCard("G5.12", "Новая карта начинается за краем старой", "Сеть Смотрителей восстановлена не как машина с готовыми ответами, а как инструмент сравнения и исследования. Рыжик отмечает первую точку за старой картой. Дальше путь снова придётся строить самим.", false, "https://www.figma.com/board/mlTEA1hlLJPYf1yRX5a739/?node-id=2055-3982"),
)
